// Hand-written dynamic handlers migrated from src/herd.ts.

import 'package:autocomplete/src/json_spec.dart';
import 'package:autocomplete/src/spec.dart';

/// The `help` subcommand's generator runs `herd list --raw` and parses each
/// line into a command name and a description (the two are separated by two or
/// more spaces).
const herdHelpCommandsPostProcessHandler =
    'manual.src_herd.spec.subcommands_8_.args.generators.postprocess';

const _herdIcon =
    'data:image/svg+xml;base64,';

/// Parses `herd list --raw` output: each non-empty line is split on two or
/// more spaces into a command name and its description.
List<FigSuggestion> _helpCommands(String output, [List<String>? tokens]) {
  tokens; // retained for the postProcess callback signature.
  final suggestions = <FigSuggestion>[];
  for (final line in output.trim().split('\n')) {
    final trimmed = line.trim();
    if (trimmed.isEmpty) continue;
    final parts = trimmed.split(RegExp(r'\s{2,}'));
    final command = parts.first;
    final description = parts.sublist(1).join(' ');
    suggestions.add(FigSuggestion(
      name: command,
      description: description.isNotEmpty ? description : null,
      icon: _herdIcon,
    ));
  }
  return suggestions;
}

/// Registers the herd dynamic handlers referenced by the shipped herd JSON.
void registerHerdHandlers(JsonHandlerRegistry registry) {
  registry.registerPostProcess(herdHelpCommandsPostProcessHandler, _helpCommands);
}
